package com.bookrush.publisherservice.api;
import java.security.Principal; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/publisher") public class PublisherMetricsController { private final JdbcTemplate jdbc; private final RestClient behavior; public PublisherMetricsController(JdbcTemplate jdbc,@Value("${publisher.behavior-url:http://behavior-service:8097}") String url){this.jdbc=jdbc; this.behavior=RestClient.builder().baseUrl(url).build();} private String s(Principal p){if(p==null||p.getName()==null||p.getName().isBlank())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"authentication required");return p.getName();}
 @GetMapping("/submissions/{id}/metrics") public Object metrics(@PathVariable UUID id,Principal p){var rows=jdbc.queryForList("select catalog_book_id from publisher.submission where id=? and subject_key=?",id,s(p));if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"submission not found");Object book=rows.getFirst().get("catalog_book_id");if(book==null)return Map.of("submissionId",id,"status","NOT_LINKED","items",List.of());Object data=behavior.get().uri("/api/v1/behavior/aggregates/books/{bookId}",book).retrieve().body(Object.class);return Map.of("submissionId",id,"catalogBookId",book,"items",data==null?List.of():data);}
}
